INSERT INTO warehouse SELECT w, CONCAT('w', w), 0 FROM nw;
INSERT INTO district SELECT d.n + 1, w.w, 3001 FROM nw w CROSS JOIN n10 d;
INSERT INTO item SELECT a.n * 100 + b.n + 1, ((a.n * 100 + b.n) % 1000) / 10.0, CONCAT('item', a.n * 100 + b.n + 1) FROM n1000 a CROSS JOIN n100 b;
INSERT INTO customer SELECT c2.n * 1000 + c1.n + 1, d.n + 1, w.w, 50000, (c1.n % 1000) * 10, CASE WHEN c1.n % 50 = 0 THEN NULL ELSE (c1.n % 2000) - 1000 END FROM (SELECT w FROM nw WHERE w >= 1 AND w < 2) w CROSS JOIN n10 d CROSS JOIN n3 c2 CROSS JOIN n1000 c1;
INSERT INTO stock SELECT a.n * 100 + b.n + 1, w.w, 100 + ((a.n + b.n) % 50) FROM (SELECT w FROM nw WHERE w >= 1 AND w < 2) w CROSS JOIN n1000 a CROSS JOIN n100 b;
INSERT INTO orders SELECT c2.n * 1000 + c1.n + 1, d.n + 1, w.w, c2.n * 1000 + c1.n + 1, NULL, 10, 1, CURRENT_TIMESTAMP FROM (SELECT w FROM nw WHERE w >= 1 AND w < 2) w CROSS JOIN n10 d CROSS JOIN n3 c2 CROSS JOIN n1000 c1;
INSERT INTO new_order SELECT c1.n + 2101, d.n + 1, w.w FROM (SELECT w FROM nw WHERE w >= 1 AND w < 2) w CROSS JOIN n10 d CROSS JOIN n1000 c1 WHERE c1.n < 900;
