INSERT INTO customer SELECT c2.n * 1000 + c1.n + 1, d.n + 1, w.w, 50000, (c1.n % 1000) * 10, CASE WHEN c1.n % 50 = 0 THEN NULL ELSE (c1.n % 2000) - 1000 END FROM (SELECT w FROM nw WHERE w >= 996 AND w < 997) w CROSS JOIN n10 d CROSS JOIN n3 c2 CROSS JOIN n1000 c1;
INSERT INTO stock SELECT a.n * 100 + b.n + 1, w.w, 100 + ((a.n + b.n) % 50) FROM (SELECT w FROM nw WHERE w >= 996 AND w < 997) w CROSS JOIN n1000 a CROSS JOIN n100 b;
